"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[361],{1759(e){e.exports=JSON.parse('{"title":"useState()\uac00 \uc544\ub2c8\ub77c \uc0c1\ud0dc\uc640 \uce5c\ud574\uc9c0\uae30","date":"2025-04-15","coverUrl":"/kudzu-based-bench/assets/notion/db653d923a79d6cd.png","html":"<h2 data-notion-block-id=\\"1d4e548d-8a8e-8049-8d15-e702077d34a3\\" id=\\"1d4e548d-8a8e-8049-8d15-e702077d34a3\\"><code>useState()</code>\uac00 \uc544\ub2c8\ub77c \uc0c1\ud0dc\uc640 \uce5c\ud574\uc9c0\uae30</h2><a href=\\"https://www.youtube.com/watch?v=aGkscOKWQvQ\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=aGkscOKWQvQ</a><p data-notion-block-id=\\"1d4e548d-8a8e-800c-8179-e7dd7256a123\\"><code>useState()</code>\uac00 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \uac00\uc9c0\uace0 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc0c1\ud669\uc5d0 \ub530\ub77c\uc11c \uc5b4\ub5a4 \uae30\uc220\uc744 \uc4f0\uba74 \uc88b\uc740\uc9c0, \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc4f0\uba74 \uc88b\uc740\uc9c0\ub97c \ubaa8\ub450 \uc124\uba85\ud558\ub294 \uc601\uc0c1\uc785\ub2c8\ub2e4. \uc0c1\ud0dc\ub97c \uc798 \uad00\ub9ac\ud558\ub294 \ubc95\uc744 \uc54c\ub354\ub77c\ub3c4, React 19\uc5d0\uc11c\uc758 \uc0c1\ud0dc \uad00\ub9ac\ubd80\ud130, <code>useSyncExternalStore()</code>(<a href=\\"https://ones-to-watch.ethansup.net/news/post/14ae548d-8a8e-8059-b8c9-cc040779dd9f#14ee548d-8a8e-80ce-af90-fa40c94a2c36\\">\uc8fc\uc758\uc810</a>), <a href=\\"https://ones-to-watch.ethansup.net/news/post/1bfe548d-8a8e-80b8-af8c-e6d92b1df9fd#1bfe548d-8a8e-80ae-a311-da196b44a7ee\\">Sync Engine</a>.. \uac19\uc774 \ubaa8\ub4e0 \uc0c1\ud0dc\uc5d0 \ub300\ud574 \uc124\uba85\ud558\uace0 \uc788\uc73c\ub2c8, \ubaa8\ub4e0 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790 \ubd84\ub4e4\uc774 \uaf2d \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4 \ud83d\ude42</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-801e-a586-e6e68c5ecfa6\\" id=\\"1d3e548d-8a8e-801e-a586-e6e68c5ecfa6\\">Next.js\ub294 \uc5b4\ub51c \ud5a5\ud574 \uac00\ub294\uac00</h2><a href=\\"https://www.netlify.com/blog/how-we-run-nextjs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.netlify.com/blog/how-we-run-nextjs/</a><p data-notion-block-id=\\"1d3e548d-8a8e-805d-b524-d5ea7c4dbd91\\">\uc774\uc804\uc758 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c3e548d-8a8e-80a7-9539-cddcd66b5f38#1c3e548d-8a8e-80fd-97e3-c81f618509ea\\">RSC\uc758 \ubcf4\uc548, \ub09c \ub2e4\ub974\uac8c \ubcf8\ub2e4</a>\uae00\uc758 <a href=\\"https://eduardoboucas.com/posts/2025-03-25-you-should-know-this-before-choosing-nextjs/\\">\ub2e4\ub978 \uae30\uc220 \uc120\ud0dd \ub610\ud55c \uace0\ub824</a>\ud574\ubcf4\ub294 \uae00\uc758 \uc5f0\uc7a5\uc120 \uc0c1\uc758 \uae00\uc785\ub2c8\ub2e4. Next.js\uc758 \uc6f9 \ud45c\uc900\uc744 \uc9c0\ud0a4\uc9c0 \uc54a\ub294 \uc810(<a href=\\"https://ones-to-watch.ethansup.net/news/post/ee307831-cb46-4aaf-b912-fff97004d37e#c591a4a0-9749-47c1-9c95-4838fa55356d\\">Monkey Patch\ub97c \ud558\uc9c0 \ub9c8\uc138\uc694</a>), \ub85c\ub4dc\ub9f5\uc774\ub098 \ubb38\uc11c\ud654\uac00 \ubd80\uc871\ud55c \uc810\uc744 \ucd94\uac00\ub85c \uc9c0\uc801\ud558\uba70 Netlify\uc5d0\uc11c\uc758 \ubc30\ud3ec \ubc29\uc2dd\uc774\ub098 OpenNext\uc5d0 \ud569\ub958\ud55c\ub2e4\ub294 \uc810, RFC\ub97c \uc791\uc131\ud55c\ub2e4\ub294 \uc810\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 \ub274\uc2a4\ub808\ud130\uc5d0\uc11c\ub3c4 Next.js\uc5d0 \uc2e4\ub9dd\ud558\uace0 Remix\ub098 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\ub85c \ubcc0\uacbd\ud558\ub294 \uae00\ub3c4 \uc2ec\uc2ec\uce58 \uc54a\uac8c \ubcfc \uc218 \uc788\uc9c0\ub9cc(<a href=\\"https://ones-to-watch.ethansup.net/news/post/37250bc2-728f-4005-9bc5-c041e79d1790#4a3e686e-6b9d-4ff1-99e8-65ffca0cb84e\\">\ub2f9\uc2e0\uc774 Remix\ub97c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \uc774\uc720</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-80c6-8224-f9618dd9926f\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uae30</a>, <a href=\\"https://documenso.com/blog/why-we-moved-off-next-js\\">Next.js\uc5d0\uc11c \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud55c \uc774\uc720</a>), <a href=\\"https://zhero-web-sec.github.io/research-and-things/react-router-and-the-remixed-path\\">Remix \ub610\ud55c \ubcf4\uc548 \uc774\uc288</a>\uc5d0\uc11c \uc790\uc720\ub86d\uc9c0 \uc54a\uace0, \ud504\ub808\uc784\uc6cc\ud06c\ub9c8\ub2e4 \ud2b9\uc131\uc774 \ub2e4\ub974\ubbc0\ub85c, \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc798 \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uc633\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-805c-ac24-df163854a6f2\\" id=\\"1d3e548d-8a8e-805c-ac24-df163854a6f2\\">\ub9ac\uc561\ud2b8 \uba54\uc778\ud14c\uc774\ub108\uac00 \ub9d0\ud558\ub294 RSC \uc544\ud0a4\ud14d\uccd0</h2><a href=\\"https://overreacted.io/react-for-two-computers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/react-for-two-computers/</a><p data-notion-block-id=\\"1d3e548d-8a8e-8019-8c88-e89480a6dc13\\">RSC\uc758 RFC\ub97c \ub9cc\ub4e4 \ub54c \ub098\uc654\ub358 \uac1c\ub150\uc778 <a href=\\"https://github.com/reactwg/server-components/discussions/4\\">Server tree\uc640 React tree\uc758 \uac1c\ub150</a>\uc774 \uc5b4\ub5bb\uac8c \uc0dd\uaca8\ub0ac\ub294\uc9c0 \uc120\uc5b8\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 JSX \ud0dc\uadf8\uc640 \uba85\ub839\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 \ud568\uc218\ub97c \uc5b4\ub5bb\uac8c \ud569\uce58\uace0 \uc2f6\uc5c8\ub294\uc9c0\ub97c \uae38\uac8c \ud480\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. \ub108\ubb34 \uae34 \uae00\uc778\ub370\ub2e4, RSC\uc758 \uadf8\ub9bc\uc744 \uc5b4\ub5bb\uac8c \uadf8\ub9ac\uace0 \uc2f6\uc5c8\ub294\uc9c0\ub97c \uac00\uc0c1\uc758 \uc5b8\uc5b4\ub85c \ud45c\ud604\ud558\uace0 \uc788\uc5b4, \ubcf4\uae30 \uc5b4\ub835\uc9c0\ub9cc \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804 \uae00\uacfc \ubc1c\ud45c\uc778 <a href=\\"https://ones-to-watch.ethansup.net/news/post/6631ddbe-1279-426c-88c7-e9e02785bbb6#9a381a1f-cb0f-4ddc-9618-f562bc5ac748\\">React \uc0ac\uc6a9\uc790\uc758 \ub450 \uac00\uc9c0 \uc811\uadfc</a>\ub3c4 \uc5f0\uad00\uc774 \uae4a\uc73c\ubbc0\ub85c \uba3c\uc800 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-8091-8089-d83d3018879c\\" id=\\"1d3e548d-8a8e-8091-8089-d83d3018879c\\">Websocket\uc758 \uc228\uaca8\uc9c4 \ube44\uc6a9</h2><a href=\\"https://hntrl.io/posts/you-dont-need-websockets/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hntrl.io/posts/you-dont-need-websockets/</a><p data-notion-block-id=\\"1d3e548d-8a8e-8011-a139-d38d75bc1a81\\">Websocket\uc774 \ubb34\uc5c7\uc778\uc9c0, Websocket\uc744 \uc0ac\uc6a9\ud558\uba74 \uc548 \uc88b\uc740 \uc0c1\ud669\uacfc \ub2e8\uc810, \uadf8\ub9ac\uace0 \uc2e4\uc81c \uc6f9 \uc0ac\uc774\ud2b8\uc5d0\uc11c \uc6b4\uc601\ud560 \ub54c \ud544\uc694\ud55c \uc694\uad6c\uc0ac\ud56d\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ub300\uccb4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ud558\uba74 \uc88b\uc740\uc9c0 \ucf54\ub4dc\uc640 \ud568\uaed8 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-8085-9585-ff6b86f1e766\\" id=\\"1d3e548d-8a8e-8085-9585-ff6b86f1e766\\">OSI\ubd80\ud130 HTTPS\uae4c\uc9c0 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.deepintodev.com/blog/how-data-travels-the-world-to-reach-your-screen\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.deepintodev.com/blog/how-data-travels-the-world-to-reach-your-screen</a><p data-notion-block-id=\\"1d4e548d-8a8e-80ee-a623-fa98a2e64f32\\">\uba74\uc811 \ub2e8\uace8 \uc9c8\ubb38\ub4e4\uc744 \uc798 \ub300\ub2f5\ud560 \uc218 \uc788\ub3c4\ub85d OSI\ubaa8\ub378, TCP \ubd80\ud130 HTTPS\uae4c\uc9c0 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://ones-to-watch.ethansup.net/news/post/141e548d-8a8e-80f8-9eac-fc41a6ef97e0#142e548d-8a8e-8078-b8ce-c60961dbae9a\\">DNS\ubd80\ud130 \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1\uae4c\uc9c0 \ub2e4\ub8ec \uae00</a>\uc774\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#de888686-3d72-4003-8a20-e36af601960c\\">HTTP\ub97c \ub525\ub2e4\uc774\ube0c\ud558\ub294 \uae00</a>\ub610\ud55c \uc77d\uc5b4\ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4 :)</p><h2 data-notion-block-id=\\"1d5e548d-8a8e-8063-8ee8-c0d994569192\\" id=\\"1d5e548d-8a8e-8063-8ee8-c0d994569192\\">JWT\ub294 \uc5b4\ub290\ub54c \uc368\uc57c\ud560\uae4c</h2><a href=\\"https://www.permit.io/blog/a-guide-to-bearer-tokens-jwt-vs-opaque-tokens\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.permit.io/blog/a-guide-to-bearer-tokens-jwt-vs-opaque-tokens</a><p data-notion-block-id=\\"1d5e548d-8a8e-802e-a36a-e2d5b42aaa12\\">JWT\uc640 Opaque Token\uc744 \uc18c\uac1c\ud558\uace0 \uac01\uc790\uc758 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\ud1b5 JWT\ub97c \uc77c\ubc18\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294\ub370, \uc7a5\ub2e8\uc810\uacfc \ubcf4\uc644\ucc45\uc744 \uc801\uc808\ud558\uac8c \uac00\uc838\uac00\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-809a-8bde-fb64b4560785\\" id=\\"1d3e548d-8a8e-809a-8bde-fb64b4560785\\"><code>React.memo</code>\uac00 \ubb38\uc81c\uac00 \ub420 \ub54c</h2><a href=\\"https://cekrem.github.io/posts/react-memo-when-it-helps-when-it-hurts/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cekrem.github.io/posts/react-memo-when-it-helps-when-it-hurts/</a><p data-notion-block-id=\\"1d3e548d-8a8e-80c6-9625-e8106ea1965a\\"><code>useCallback()</code>, <code>useMemo()</code>\uc5d0 \ub300\ud574 \uac04\ub2e8\ud558\uac8c \uc54c\uc544\ubcf4\uace0 \uc77c\ubc18\uc801\uc73c\ub85c \uac04\uacfc\ud560 \uc218 \uc788\ub294 \ubb38\uc81c, \ub80c\ub354\ub9c1\uc774 \uc624\ub798\uac78\ub9ac\ub294 \ucef4\ud3ec\ub10c\ud2b8\uc5d0 \ub300\ud55c \ub2e4\ub978 \ud574\uacb0\ucc45\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-8065-9c6e-ef3c5a7a556f\\" id=\\"1d3e548d-8a8e-8065-9c6e-ef3c5a7a556f\\">Electron\uacfc Tauri\uc758 \uc544\ud0a4\ud14d\uccd0 \ucc28\uc774\uc810</h2><a href=\\"https://gethopp.app/blog/tauri-vs-electron\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gethopp.app/blog/tauri-vs-electron</a><p data-notion-block-id=\\"1d5e548d-8a8e-802e-9ca7-ddd91593cbdc\\">Electron\uacfc Tauri\uc758 \uad6c\ub3d9\ubc29\uc2dd\uacfc \uae30\ub2a5\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc7a5\ub2e8\uc810\uacfc \uad6c\ub3d9\ubc29\uc2dd\uae4c\uc9c0 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ubbc0\ub85c \ub370\uc2a4\ud06c\ud0d1 \uc571\uc5d0 \uad00\uc2ec\uc788\uc73c\uc2e0 \ubd84\uc740 \ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"1d5e548d-8a8e-8015-889f-d91c2027bbca\\" id=\\"1d5e548d-8a8e-8015-889f-d91c2027bbca\\">\ub54c\ub85c\ub294 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4</h2><a href=\\"https://www.youtube.com/watch?v=i1cVfJz4Vlw\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=i1cVfJz4Vlw</a><p data-notion-block-id=\\"1d5e548d-8a8e-80e6-95f0-fd39f2c9b7eb\\">Remix\uc758 loader - component - action \ud328\ud134\uc758 \ub2e8\uc810\uc744 react-hook-form\uacfc tanstack query\uc73c\ub85c \uc808\ucda9\ud558\ub294 \ubc29\ubc95\uc744 \ubc1c\ud45c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc9c0\uc5fd\uc801\uc778 \ubd80\ubd84\uc5d0 \ub300\ud55c \ucf00\uc774\uc2a4\ub97c \ud480\uc5b4\ub098\uac00\ub294 \ubc1c\ud45c\uc9c0\ub9cc, \ud544\uc694\uc2dc\uc5d0 \ub530\ub77c\uc11c \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc81c\uc548\ud558\ub294 \ubc29\ubc95 \ub300\uc2e0 \ub2e4\ub978 \ubc29\ubc95\uc744 \uc5b4\ub5bb\uac8c \ucc3e\uace0, \uc801\uc6a9\ud558\ub294\uc9c0\uc5d0 \ub300\ud55c \ubc29\ubc95\ub860\uc740 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cfe548d-8a8e-805c-8db9-c59a86dda5b7\\" id=\\"1cfe548d-8a8e-805c-8db9-c59a86dda5b7\\">React\uc5d0\uc11c \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\ub294 \uc811\uadfc\uc131 \uc694\uc18c\ub4e4</h2><a href=\\"https://www.youtube.com/watch?v=tFO0-aMxitY\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=tFO0-aMxitY</a><p data-notion-block-id=\\"1d5e548d-8a8e-80ea-ace2-eeb3c203a704\\">\ub9ce\uc774\ub4e4 \uc544\ub294 \uc2dc\ub9e8\ud2f1 \ud0dc\uadf8\uc5d0\uc11c\ubd80\ud130 \uc88b\uc740 \uc811\uadfc\uc131\uc744 \uac04\ub2e8\ud558\uac8c \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \ub9ce\uc740 \uac83\uc744 \uc18c\uac1c\ud558\uc9c4 \uc54a\uc9c0\ub9cc, \ub204\uad6c\ub098 \uc801\uc6a9\ud560 \uc218 \uc788\uc744\ub9cc\ud07c \uc26c\uc6b4 \uac83\ub4e4\uc774\uae30\uc5d0 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"1d4e548d-8a8e-803f-b942-c508f6bb74d2\\" id=\\"1d4e548d-8a8e-803f-b942-c508f6bb74d2\\">\uba54\ubaa8\ub9ac \ub204\uc218 \ub514\ubc84\uae45\ud558\uae30</h2><a href=\\"https://bun.sh/blog/debugging-memory-leaks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bun.sh/blog/debugging-memory-leaks</a><p data-notion-block-id=\\"1d5e548d-8a8e-8002-b90b-d4f7080fd428\\">V8\uacfc JSC\uc758 \ud799 \uc2a4\ub0c5\uc0f7\uc744 \ubcf4\ub294 \ubc95(\ubb3c\ub860 bun\uc744 \uc0ac\uc6a9\ud574\uc11c)\uacfc \uc77c\ubc18\uc801\uc73c\ub85c \uba54\ubaa8\ub9ac \ub204\uc218\uac00 \uc77c\uc5b4\ub098\ub294 \uc0c1\ud669\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d5e548d-8a8e-80ca-9867-cc42340a03ef\\" id=\\"1d5e548d-8a8e-80ca-9867-cc42340a03ef\\">\uccb4\uacc4\uc801\uc73c\ub85c \ub9ac\uc561\ud2b8 \ud30c\uc77c\uad6c\uc870 \ub9cc\ub4e4\uae30</h2><a href=\\"https://playfulprogramming.com/posts/layered-react-structure#lrs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://playfulprogramming.com/posts/layered-react-structure#lrs</a><p data-notion-block-id=\\"1d5e548d-8a8e-8087-bdd3-dafd55c08792\\">\ubaa8\ub4e0 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc801\uc6a9\ud560 \uc218 \uc788\uc744 \uc218\ub3c4 \uc5c6\uc744 \uc218\ub3c4 \uc788\ub294 \ud30c\uc77c\uad6c\uc870 \uc544\ud0a4\ud14d\uccd0\uc9c0\ub9cc, Smart-Dumb \ucef4\ud3ec\ub10c\ud2b8 \uac1c\ub150\uc744 \ub3c4\uc785\ud574 \ubd84\ub9ac\ud558\ub294 \uc810\uacfc \uc720\ud2f8\ub9ac\ud2f0/\uc11c\ube44\uc2a4 \ubd84\ub9ac\ud558\ub294 \uc810\uc740 \uba85\ud655\ud558\uac8c \ub2e4\uac00\uc640\uc11c \uc798 \uc801\uc6a9\ud560 \uc218 \uc788\uc744 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"1d4e548d-8a8e-80f9-ae71-c237a515b6a5\\" id=\\"1d4e548d-8a8e-80f9-ae71-c237a515b6a5\\">LLM\uc744 \ud1b5\ud574 \ud504\ub808\uc784\uc6cc\ud06c \ub9c8\uc774\uadf8\ub808\uc774\uc158</h2><a href=\\"https://medium.com/airbnb-engineering/accelerating-large-scale-test-migration-with-llms-9565c208023b\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/airbnb-engineering/accelerating-large-scale-test-migration-with-llms-9565c208023b</a><p data-notion-block-id=\\"1d5e548d-8a8e-80c1-a11c-d15b888f1c1b\\">LLM\uc744 \ud1b5\ud574 Enzyme\uc5d0\uc11c RTL\ub85c \ucf54\ub4dc\ub97c \ubcc0\uacbd\ud558\ub294\ub370 \uc2dc\uac04\uc744 \ub2e8\ucd95\ud55c \uc7ac\ubbf8\uc788\ub294 \uae00\uc785\ub2c8\ub2e4. LLM\uc744 \uc5b4\ub5bb\uac8c \ud65c\uc6a9 \uc804\ub7b5\uc744 \uc9e4 \uac83\uc778\uc9c0 \ub3c4\uc6c0\uc774 \ub420 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"1d4e548d-8a8e-8090-bf5c-db53fcec68ba\\" id=\\"1d4e548d-8a8e-8090-bf5c-db53fcec68ba\\">Reconciliation\uc758 \uc791\ub3d9 \ubc29\uc2dd</h2><a href=\\"https://cekrem.github.io/posts/react-reconciliation-deep-dive/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cekrem.github.io/posts/react-reconciliation-deep-dive/</a><p data-notion-block-id=\\"1d5e548d-8a8e-8098-94e9-c76abfe77ac5\\">\uac04\ub2e8\ud558\uac8c \uc54c\uc544\ubcf8 recolnciliation \uacfc\uc815\uc785\ub2c8\ub2e4. \ub354 \uc790\uc138\ud788 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740 \ubd84\uc740 <a href=\\"https://jser.dev/react/2022/01/07/how-does-bailout-work\\">reconciliation \ub525\ub2e4\uc774\ube0c</a>\ub97c \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d3e548d-8a8e-80cc-a0d6-f9008453d8fe\\" id=\\"1d3e548d-8a8e-80cc-a0d6-f9008453d8fe\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://nextjs.org/blog/next-15-3\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15-3</a><p data-notion-block-id=\\"1d3e548d-8a8e-8014-81ea-c34581c592c2\\">turbopack\uc73c\ub85c \ube4c\ub4dc\ub97c \ud560 \uc218 \uc788\ub294 Next.js 15.3 \ubc84\uc804\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://pears.com/news/introducing-bare-actually-run-javascript-everywhere/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pears.com/news/introducing-bare-actually-run-javascript-everywhere/</a><p data-notion-block-id=\\"1d3e548d-8a8e-80fc-82f8-fba09104f850\\">JS\ub97c \uc5b4\ub514\uc11c\ub4e0 \uac00\ubccd\uac8c \ub3cc\ub9b4 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e0 \uc5d4\uc9c4\uc778 Bare \uc5d4\uc9c4\uc785\ub2c8\ub2e4.</p><a href=\\"https://reactnative.dev/blog/2025/04/08/react-native-0.79\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2025/04/08/react-native-0.79</a><p data-notion-block-id=\\"1d4e548d-8a8e-8019-81ce-f778092004b7\\">React Native 0.79 \ucd9c\uc2dc \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc18d\ub3c4\uac00 \ub9ce\uc774 \ube68\ub77c\uc84c\ub2e4\ub294 \uac83\uc744 \uac15\uc870\ud558\ub124\uc694.</p><a href=\\"https://blog.cloudflare.com/deploying-nextjs-apps-to-cloudflare-workers-with-the-opennext-adapter/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/deploying-nextjs-apps-to-cloudflare-workers-with-the-opennext-adapter/</a><p data-notion-block-id=\\"1d5e548d-8a8e-80c0-909d-e7fead385912\\">OpenNext\ub97c \ud1b5\ud574 Next.js \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 Cloudflare workers\uc5d0 \ubc30\ud3ec\ud558\uae30 \uc26c\uc6cc\uc84c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);